fn validate_field(name: &str, value: &Value, schema: &FieldSchema) -> Result<(), String> { … }

pub(crate) fn validate_value_against_type(
    name: &str,
    value: &Value,
    field_type: &FieldType,
) -> Result<(), String> { … }

fn validate_object_fields(
    name: &str,
    value: &Value,
